do

{

Status |= vl53l0x\_init(&vl53l0x\_dev);                         //VL53L0X\_DataInit()

Status |= VL53L0X\_StaticInit(&vl53l0x\_dev);

// Status |= VL53L0X\_SetDeviceMode(&vl53l0x\_dev,VL53L0X\_DEVICEMODE\_CONTINUOUS\_TIMED\_RANGING);

GPIOB\_InverseBits(OBJ\_LED);

mDelayuS(500);

}while(Status != VL53L0X\_ERROR\_NONE);                            //如果TOF有问题或接触不良，LED会以2Hz频率闪烁

while(1)

{

Status = VL53L0X\_ERROR\_NONE;

KEY\_SCAN();

if(KEY3\_PRESS\_flag)                //RST键(要改造)  不需要?特定的光照条件。室内正常光线即可，校准期间，确保传感器前方 ?1 米内无遮挡物?，或者至少保持开阔空间

{//第一步

GPIOB\_SetBits(OBJ\_LED);;        //让LED灭，不影响标定

KEY3\_PRESS\_flag = 0;

VL53L0X\_GetReferenceSpads(&vl53l0x\_dev,&myrefSpadCount\_readout,&myisApertureSpads\_readout);  //初始值myrefSpadCount\_readout=5，myisApertureSpads\_readout =0

mDelayuS(20);

Status = VL53L0X\_PerformRefSpadManagement(&vl53l0x\_dev,&myrefSpadCount,&myisApertureSpads);  //执行参考Spad管理 refSpadCount = 8;isApertureSpads= 1

if(Status == VL53L0X\_ERROR\_NONE)

{

VL53L0X\_GetReferenceSpads(&vl53l0x\_dev,&myrefSpadCount\_readout,&myisApertureSpads\_readout);  //执行Spad校准后 refSpadCount = 8;isApertureSpads= 1

Write\_eeprom(refSpadCount\_addr,&myrefSpadCount,sizeof(myrefSpadCount));

Write\_eeprom(isApertureSpads\_addr,&myisApertureSpads,sizeof(myisApertureSpads));

Read\_eeprom(refSpadCount\_addr,&myrefSpadCount\_readout,sizeof(myrefSpadCount\_readout));

Read\_eeprom(isApertureSpads\_addr,&myisApertureSpads\_readout,sizeof(myisApertureSpads\_readout));

if((myrefSpadCount != myrefSpadCount\_readout) && (myisApertureSpads\_readout != myisApertureSpads ) )

{

goto ERR1;

}

}

else

{

goto ERR1;                                       //让LED灭，表示标定不成功

}

//Status |= VL53L0X\_StaticInit(&vl53l0x\_dev);

Status |= VL53L0X\_PerformRefCalibration(&vl53l0x\_dev, &myVhvSettings, &myPhaseCal);//Ref参考校准   (如果中断充许,则会产生中断，中断会被清除)

if(Status == VL53L0X\_ERROR\_NONE)

{

VL53L0X\_GetReferenceSpads(&vl53l0x\_dev,&myrefSpadCount\_readout,&myisApertureSpads\_readout);

Write\_eeprom(VhvSettings\_addr,&myVhvSettings,sizeof(myVhvSettings));

Read\_eeprom(VhvSettings\_addr,&myVhvSetting\_readout,sizeof(myVhvSetting\_readout));

if(myVhvSettings != myVhvSetting\_readout) goto ERR1;

Write\_eeprom(PhaseCal\_addr,&myPhaseCal,sizeof(myPhaseCal));

Read\_eeprom(PhaseCal\_addr,&myPhaseCal\_readout,sizeof(myPhaseCal\_readout));

if(myPhaseCal == myPhaseCal\_readout)

GPIOB\_ResetBits(OBJ\_LED);                         //让LED亮

else

goto ERR1 ;

}

else

{

ERR1:       GPIOB\_SetBits(OBJ\_LED);                           //让LED灭，表示标定不成功

}

}

else if(KEY2\_PRESS\_flag)     //Download键  做offset键

{//第二步 暗环境 100mm

GPIOB\_SetBits(OBJ\_LED);;                               //让LED灭，不影响标定

KEY2\_PRESS\_flag = 0 ;

mDelayuS(20);

Status |= VL53L0X\_PerformOffsetCalibration(&vl53l0x\_dev,myCalDistanceMilliMeter,&myOffsetMicroMeter);//长距离

if(Status == VL53L0X\_ERROR\_NONE)

{

Write\_eeprom(pOffsetMicroMeter\_addr,&myOffsetMicroMeter,sizeof(myOffsetMicroMeter));    //把标定的结果写入EEPROM

Read\_eeprom(pOffsetMicroMeter\_addr,&myOffsetMicroMeter\_readout,sizeof(myOffsetMicroMeter\_readout));

if(myOffsetMicroMeter == myOffsetMicroMeter\_readout)

GPIOB\_ResetBits(OBJ\_LED);                          //让LED亮

else

goto ERR2;

}

else

{

ERR2:       GPIOB\_SetBits(OBJ\_LED);;                          //让LED灭，表示标定不成功

}

}

//串扰校准-----------------------------------------------------

else if(KEY1\_PRESS\_flag)       //KEY键  做XTALK

{//第三步 600mm 最好暗环境

GPIOB\_SetBits(OBJ\_LED);;                               //让LED灭，不影响标定

KEY1\_PRESS\_flag = 0;

mDelayuS(20);

Status |= VL53L0X\_PerformXTalkCalibration(&vl53l0x\_dev,(600<<16),&myXTalkCompensationRateMegaCps);    //现是600mm,我知道要以实际实际测距拐点为准，但一般为450--600mm

if(Status == VL53L0X\_ERROR\_NONE)

{

Write\_eeprom(pXTalkCompensationRateMegaCps\_addr,&myXTalkCompensationRateMegaCps,sizeof(myXTalkCompensationRateMegaCps));

Read\_eeprom(pXTalkCompensationRateMegaCps\_addr,&myXTalkCompensationRateMegaCps\_readout,sizeof(myXTalkCompensationRateMegaCps\_readout));

if(myXTalkCompensationRateMegaCps == myXTalkCompensationRateMegaCps\_readout)

GPIOB\_ResetBits(OBJ\_LED);                          //让LED亮

else

{

goto ERR3;

}

}

else

{

ERR3:       GPIOB\_SetBits(OBJ\_LED);;                          //让LED灭，表示标定不成功

}

}
